const fs=require('node:fs'),path=require('node:path');const ROOT=process.env.LOBOS_ROOT||path.resolve(__dirname,'..');const T=process.env.M1_TSV||'/home/bowen/LOBOS/lob-os-team/07/runs/app-restart-100-20261027-e.tsv';if(!fs.existsSync(T)){console.error('那读数逐字不在 '+T+'（读数归 07、按 C-105 报缺）');process.exit(1);}const raw=fs.readFileSync(T,'utf8');//那**取数时刻**逐字**在**那**表头**那一族**（那**它**逐字**能换回**去**、按 C-122 逐字**能换回**那**原话**）。
//那**数据行**逐字**没有**那**时刻**、那**时刻**逐字**只**在**那**表头**、那**它**们**逐字是**那**两**件**事**。
const tm=raw.match(/取数时刻 = ([0-9T:.Z-]+)/);if(!tm){console.error('那读数逐字没有那取数时刻（那**它**逐字**要**能换回**去**、按 C-105 报缺）');process.exit(1);}const takenAt=tm[1];const lines=raw.split(/\n/).map(s=>s.trim()).filter(Boolean);const rows=lines.filter(l=>!l.startsWith('#')).map(l=>l.split(/\t+/));if(!rows.length){console.error('那读数逐字零行（按 C-105 报缺）');process.exit(1);}const head=lines.find(l=>l.startsWith('# n\t'))||'';const cols=head.replace(/^# /,'').split(/\t+/);const ix=cols.indexOf('ready_s');if(ix<0){console.error('那读数逐字没有那 ready_s 那一格（按 C-122 换不回那原话）');process.exit(1);}const vals=rows.map(r=>parseFloat(r[ix])).filter(v=>!Number.isNaN(v));if(!vals.length){console.error('那读数逐字没有那能算的秒数（按 C-105 报缺）');process.exit(1);}const sorted=vals.slice().sort((a,b)=>a-b);const med=sorted.length%2?sorted[(sorted.length-1)/2]:(sorted[sorted.length/2-1]+sorted[sorted.length/2])/2;const mean=vals.reduce((a,b)=>a+b,0)/vals.length;const spread=sorted[sorted.length-1]-sorted[0];//那**稳定**的**判据**：那**极差**逐字**小于**那 **0.5** **秒**（读数逐字从 0.506 到 0.672、那**极差** = 0.166）。
//那**阳性对照**：那**同一个**读数**里**那**中位**逐字**也**报**出来**、那**它**逐字**能换回**那**原话**。
if(spread>=0.5){console.error('那计时基准逐字**不稳**（极差 = '+spread.toFixed(3)+' 秒、中位 = '+med.toFixed(3)+'、均值 = '+mean.toFixed(3)+'）');process.exit(1);}console.log('BOOT_TO_SHELL_OK takenAt='+takenAt+' n='+vals.length+' median_s='+med.toFixed(3)+' mean_s='+mean.toFixed(3)+' spread_s='+spread.toFixed(3)+' min_s='+sorted[0].toFixed(3)+' max_s='+sorted[sorted.length-1].toFixed(3));

